/* Neon base adapter for the Immersive Themes: a [data-immersive-theme] scope
 * points shadcn/ui's slots at the theme's --immersive-* properties, so
 * everything inside takes the theme. ImmersiveLayout imports this file and
 * sets the attribute on its root and on <html>. immersive-themes.css is
 * generated by theme/scripts/generate-immersive-themes.mjs, copied as-is. */
@import "./immersive-themes.css";

/* <html> carries the attribute too, so the body, the overscroll and overlays
 * portalled into the body take the canvas. On <html> the first selector ties
 * neon.css's :root[data-theme] blocks and wins by coming after it.
 * A theme's text is White or Navy only, so muted text is the theme's text
 * too, and cards and popovers sit on the canvas so it stays readable there.
 * Secondary, muted and accent fills (secondary and outline buttons, toggles,
 * the segmented control track, fields, menu items) carry the theme's text,
 * not their own foreground, so they take
 * palette 75: the first stepped block on a theme whose palette 100 is the
 * canvas, and the one step whose on-color is the theme's text in every theme.
 * Accent equals secondary, as bgAlternate equals bgSecondary in Neon. Inverse
 * (the tooltip) is the action pair, since a theme's action is its text color
 * and on-action is White or Navy. The controls retuned to Core restate their
 * slots the same way: a field, a toggle and a segment's Hover are palette 75,
 * their strokes, icons, placeholder and helper the theme's text, and their
 * Disabled the Button's (the fill's CDS blend and the text, each at half
 * strength on the canvas). A pressed toggle and the chosen segment show by a
 * ring in the theme's text; the chosen segment sits on the canvas. The switch
 * is the action when on and the action at half strength when off, under a
 * thumb in on-action. The display items retuned to Core do the same: a
 * progress bar's and a spinner's track and a table's header row are palette
 * 75, the indicator, the arc and an avatar the action (its initial in
 * on-action), and a chevron the theme's text. The
 * fgPrimary role (the informational alert's icon, a ghost
 * input button) is the theme's text, or Ultra would draw it navy on navy.
 * The Button's states are restated, since Core's are for its own colors. The
 * primary's Hover and Active let 10% of what is behind show through, and its
 * Disabled is the action at half strength on the canvas under a label at half
 * strength: CDS's blend (93.7% for every theme's far-apart action and canvas)
 * under its 50% opacity. The secondary fill, and the Hover of a secondary or
 * ghost Button, are palette 75 like the other secondary fills; every other
 * Button's Disabled is that fill's CDS blend (75%) at half strength under the
 * theme's text at half strength. A link Button is the theme's text. The
 * secondary disabled mix, which no registry item reads any more, is
 * redeclared for apps that use it, because :root's mix resolves :root's
 * slots. Borders, the invalid stroke, destructive and the Button's Brand and
 * Inverse keep the app's roles. */
:root[data-immersive-theme],
[data-immersive-theme] {
  --background: var(--immersive-canvas);
  --foreground: var(--immersive-text);
  --muted-foreground: var(--immersive-text);
  --card: var(--immersive-canvas);
  --card-foreground: var(--immersive-text);
  --popover: var(--immersive-canvas);
  --popover-foreground: var(--immersive-text);
  --primary: var(--immersive-action);
  --primary-foreground: var(--immersive-on-action);
  --primary-hover: color-mix(in srgb, var(--immersive-action) 90%, transparent);
  --primary-active: color-mix(in srgb, var(--immersive-action) 90%, transparent);
  --primary-disabled: color-mix(in srgb, var(--immersive-action) 46.85%, var(--immersive-canvas));
  --primary-disabled-foreground: color-mix(in srgb, var(--immersive-on-action) 50%, var(--immersive-canvas));
  --secondary: var(--immersive-palette-75);
  --secondary-foreground: var(--immersive-on-palette-75);
  --secondary-disabled: color-mix(in srgb, var(--immersive-palette-75) 75%, var(--immersive-canvas));
  --button-secondary: var(--immersive-palette-75);
  --button-secondary-hover: var(--immersive-palette-75);
  --button-secondary-active: var(--immersive-palette-75);
  --button-disabled: color-mix(in srgb, var(--immersive-palette-75) 37.5%, var(--immersive-canvas));
  --button-disabled-foreground: color-mix(in srgb, var(--immersive-text) 50%, var(--immersive-canvas));
  --link: var(--immersive-text);
  --link-hover: var(--immersive-text);
  --field: var(--immersive-palette-75);
  --field-hover: var(--immersive-palette-75);
  --field-disabled: color-mix(in srgb, var(--immersive-palette-75) 37.5%, var(--immersive-canvas));
  --line-strong: var(--immersive-text);
  --line-disabled: color-mix(in srgb, var(--immersive-text) 50%, var(--immersive-canvas));
  --placeholder: var(--immersive-text);
  --helper: var(--immersive-text);
  --icon: var(--immersive-text);
  --icon-disabled: color-mix(in srgb, var(--immersive-text) 50%, var(--immersive-canvas));
  --disabled-foreground: color-mix(in srgb, var(--immersive-text) 50%, var(--immersive-canvas));
  --switch-off: color-mix(in srgb, var(--immersive-action) 50%, var(--immersive-canvas));
  --switch-on: var(--immersive-action);
  --switch-thumb: var(--immersive-on-action);
  --switch-thumb-disabled: color-mix(in srgb, var(--immersive-on-action) 50%, transparent);
  --layer-hover: var(--immersive-palette-75);
  --layer-active: var(--immersive-palette-75);
  --layer-selected: var(--immersive-palette-75);
  --selection-tag: var(--immersive-palette-75);
  --selection-tag-hover: var(--immersive-palette-75);
  --selection-tag-disabled: color-mix(in srgb, var(--immersive-palette-75) 37.5%, var(--immersive-canvas));
  --selection-tag-foreground: var(--immersive-on-palette-75);
  --selection-tag-border: var(--immersive-palette-75);
  --track: var(--immersive-palette-75);
  --info: var(--immersive-action);
  --interactive: var(--immersive-action);
  --layer-02: var(--immersive-palette-75);
  --icon-muted: var(--immersive-text);
  --avatar: var(--immersive-action);
  --avatar-foreground: var(--immersive-on-action);
  --muted: var(--immersive-palette-75);
  --accent: var(--immersive-palette-75);
  --accent-foreground: var(--immersive-on-palette-75);
  --inverse: var(--immersive-action);
  --inverse-foreground: var(--immersive-on-action);
  --color-fgPrimary: var(--immersive-text);
  --ring: var(--immersive-action);
}

/* The canvas sets color-scheme, whatever the OS or AppRoot says: dark only on
 * Ultra's navy. AppRoot writes color-scheme inline on <html>, so these need
 * !important. ImmersiveLayout's THEME_SCHEMES holds the same choice. */
:root[data-immersive-theme] { color-scheme: light !important; }
:root[data-immersive-theme="ultra"] { color-scheme: dark !important; }
